const products=[
{id:'keynade-mx',name:'Keynade MX',en:'12-KEY MECHANICAL FIDGET',type:'press',format:'Printed object',color:'#eee8de',art:'photo',image:'keynade/01-front-retouched-v2.jpg',price:499,verified:true,desc:'Twelve independent mechanical keys. Keyboard feel in the palm of your hand.',detail:'A grenade-shaped mechanical fidget for everyday breaks. Twelve large panels press independently; the small panels are fixed details. Turn it in your hand and find your next key.',mark:'01'},
{id:'cloud-key',name:'Key-switch charms',en:'TAKE JOY WITH YOU',type:'press',format:'Printed object',color:'#f6dfab',art:'cloud',desc:'Carry a little cloud of happiness.',detail:'Charms that bring key-switch play along with you. Final listings will confirm photos, specifications and parts.',mark:'02'},
{id:'spin-ring',name:'Spin fidgets',en:'ROUND & ROUND',type:'spin',format:'Printed object',color:'#f1c6b5',art:'spin',desc:'A gentle spin for a lighter moment.',detail:'A category of finger-spun fidgets. Final listings will confirm designs, structure and parts.',mark:'03'},
{id:'good-file',name:'Digital design files',en:'MAKE YOUR OWN GOOD',type:'file',format:'Digital files',color:'#cfdfcd',art:'file',desc:'Bring a good idea to life with your own printer.',detail:'For makers who want to print and assemble their own. Final listings will confirm images, formats, parts and license terms.',mark:'04'}];
function assetUrl(path){return (/\/(en|zh-cn)\//.test(location.pathname)?'../assets/':'assets/')+path;}
function priceLabel(p){return p.price?'NT$'+p.price:'NT$ · Price not announced';}
function art(p){if(p.image)return `<img class="real-product-image" src="${assetUrl(p.image)}" alt="Original front photograph of the gold Keynade MX" loading="lazy" decoding="async">`;if(p.type==='file')return `<span class="photo-slot"><span class="slot-type">Digital goods</span><strong>Digital designs</strong><small>Print your own · No physical product</small></span>`;return `<span class="photo-slot" aria-hidden="true"></span>`}

const qs=s=>document.querySelector(s);
const makerWorldProfile='https://makerworld.com/en/@OGStudio';
// Set verified live product URLs here once the store is open.
const saleLinks={};
let filter='all';
function buyAction(p){const url=saleLinks[p.id];if(url&&/^https:\/\/myship\.7-11\.com\.tw\//.test(url))return `<a class="button yellow" href="${url}" target="_blank" rel="noopener noreferrer">Buy on 7-ELEVEN MyShip</a>`;return '<span class="sale-status">Not yet on sale</span>';}
function renderProducts(){if(!qs('#products'))return;qs('#products').innerHTML=products.filter(p=>document.body.dataset.catalog==='digital'?p.type==='file':p.type!=='file'&&(filter==='all'||p.type===filter)).map(p=>`<article class="product-card"><button class="product-art" style="background:${p.color}" data-detail="${p.id}" aria-label="View ${p.name} details">${art(p)}${p.type==='file'?`<span class="card-stamp">${p.format}</span>`:''}<span class="art-index">OGS / ${p.mark}</span></button><div class="product-info"><div class="product-meta"><span>${p.en}</span><span>${p.verified?'12 KEYS':'Product category'}</span></div><h3><button class="title-link" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="card-bottom"><span>${priceLabel(p)}</span><button class="text-button card-details" data-detail="${p.id}">View details</button></div></div></article>`).join('');}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts();}
function detail(id){const p=products.find(p=>p.id===id);if(!p)return;if(p.type!=='file'){location.href='product.html?id='+encodeURIComponent(id);return;}qs('#product-detail').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en}</span><h2>${p.name}</h2><p>${p.detail}</p><span class="pill">Digital goods · No physical product included</span><p class="detail-note">Design files are not yet on sale. Final listings will confirm contents and license terms.</p><a class="button mint" href="${makerWorldProfile}" target="_blank" rel="noopener noreferrer">Our designs on MakerWorld</a></div></div>`;qs('#product-dialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.detail)detail(b.dataset.detail);if(b.hasAttribute('data-close'))b.closest('dialog').close();});
qs('#open-info').onclick=()=>qs('#info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
qs('#year').textContent=new Date().getFullYear();renderProducts();
const profileSlot=qs('#makerworld-profile');if(profileSlot){const link=document.createElement('a');link.className='button mint';link.href=makerWorldProfile;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Our designs on MakerWorld';profileSlot.append(link);profileSlot.hidden=false;}
const pageLinks={home:'index.html',products:'products.html',designs:'design-files.html',about:'about.html',product:'products.html'};document.querySelectorAll('header nav:not(.language-switch) a,.catalog-nav a').forEach(a=>{if(a.getAttribute('href')===pageLinks[document.body.dataset.page])a.setAttribute('aria-current','page');});
const keynadePhotos=[{file:'keynade/01-front-retouched-v2.jpg',label:'Front view'},{file:'keynade/02-side-retouched-v2.jpg',label:'Side view'},{file:'keynade/03-top-and-pin-retouched-v2.jpg',label:'Top and decorative pin'}];
if(qs('#full-product')){const id=new URLSearchParams(location.search).get('id');const p=products.find(p=>p.id===(id==='good-key'?'keynade-mx':id)&&p.type!=='file');if(!p){qs('#full-product').innerHTML='<h1>Product not found.</h1><p>Please return to physical goods and choose another item.</p><a class="button yellow" href="products.html">Browse physical goods</a>';}else if(p.id==='keynade-mx'){renderKeynade(p);}else{document.title=p.name+' — One Goods Studio';qs('#full-product').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en} / ${p.type==='press'?'Press':'Spin'}</span><h1>${p.name}</h1><span class="pill">Physical goods</span><p>${p.detail}</p><p><strong>NT$ · Price not announced</strong></p>${buyAction(p)}<div class="product-purchase-note"><b>Order through 7-ELEVEN MyShip</b><p class="detail-note">Final listings will confirm photos, materials, dimensions and prices. Products are not yet on sale.</p></div></div></div>`;}}


function renderKeynade(p){document.title='Keynade MX — One Goods Studio';qs('#full-product').innerHTML=`<div class="keynade-intro"><div class="keynade-gallery"><figure><img id="keynade-main-photo" src="${assetUrl(keynadePhotos[0].file)}" alt="Keynade MX · ${keynadePhotos[0].label}"><figcaption id="keynade-caption">${keynadePhotos[0].label}</figcaption></figure><div class="gallery-thumbs" role="group" aria-label="Product photo views">${keynadePhotos.map((photo,i)=>`<button data-gallery-index="${i}" aria-label="${photo.label}" aria-pressed="${i===0}"><img src="${assetUrl(photo.file)}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="keynade-summary"><span class="eyebrow">KEYNADE MX / PRESS & RELAX</span><h1>Keynade MX</h1><p class="keynade-subtitle">12-Key Mechanical Fidget Grenade</p><p>${p.detail}</p><div class="keynade-facts"><span><b>12</b>Independent keys</span><span><b>MX</b>Switch format</span><span><b>1</b>Ball chain included</span></div><p class="keynade-price">NT$499</p><span class="sale-status">Not yet on sale</span><p class="detail-note">Fully assembled, with 12 switches installed and one metal ball chain included.</p></div></div><section class="keynade-details"><div><span class="eyebrow">THE LITTLE DETAILS</span><h2>A little more feel in every press.</h2><p>The twelve large geometric panels are independent mechanical keys. The top pin pulls out and slides back in as a decorative, hands-on detail.</p><p>Visible 3D print layers and gold sparkle are part of the real object. Sound and feel depend on the installed switches.</p></div><div class="keynade-specs"><h2>Specifications and included items</h2><dl><div><dt>Product</dt><dd>Keynade MX</dd></div><div><dt>Key count</dt><dd>12 independent mechanical keys</dd></div><div><dt>Switch format</dt><dd>MX-Style</dd></div><div><dt>Finish</dt><dd>Gold sparkle, as photographed</dd></div><div><dt>Assembled product</dt><dd>1 assembled Keynade MX with 12 switches installed</dd></div><div><dt>Included accessory</dt><dd>1 metal ball chain</dd></div><div><dt>Price</dt><dd>NT$499 · Not yet on sale</dd></div></dl></div></section><section class="keynade-notes"><h2>About this little object</h2><p>The top pin is decorative. Small panels are fixed; twelve large panels can be pressed. Scene props in the photographs are not included.</p><p>Product photos are AI-assisted to harmonize color, lighting and backgrounds.</p><p>Product information only. Not yet on sale.</p></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery-index]');if(!b)return;const photo=keynadePhotos[Number(b.dataset.galleryIndex)];if(!photo)return;qs('#keynade-main-photo').src=assetUrl(photo.file);qs('#keynade-main-photo').alt='Keynade MX · '+photo.label;qs('#keynade-caption').textContent=photo.label;document.querySelectorAll('[data-gallery-index]').forEach(button=>button.setAttribute('aria-pressed',button===b));});
